import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Menu, X } from "lucide-react";

const links = [
  { label: "About", href: "#about" },
  { label: "Collections", href: "#collections" },
  { label: "Portfolio", href: "#portfolio" },
  { label: "Contact", href: "#contact" },
];

// Nav link hover animation
const linkVariants = {
  initial: { opacity: 0.7 },
  hover: { opacity: 1, color: "#d4af37" }
};

// Button animation
const buttonVariants = {
  rest: { scale: 1 },
  hover: { scale: 1.05, y: -2 },
  tap: { scale: 0.98 }
};

// Mobile menu animation
const menuVariants = {
  hidden: { opacity: 0, y: -20, scale: 0.95 },
  visible: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { duration: 0.3, ease: "easeOut" }
  },
  exit: {
    opacity: 0,
    y: -20,
    scale: 0.95,
    transition: { duration: 0.2, ease: "easeIn" }
  }
};

// Menu link stagger animation
const menuLinkVariants = {
  hidden: { opacity: 0, x: -20 },
  visible: (i) => ({
    opacity: 1,
    x: 0,
    transition: { delay: i * 0.1, duration: 0.3 }
  })
};

export default function Navbar({ onOpenQuote }) {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <motion.header
      className={`fixed top-0 inset-x-0 z-40 transition-all duration-500 ${scrolled ? "py-3 bg-white/95 backdrop-blur-xl shadow-lg" : "py-6 bg-transparent"}`}
      style={{ borderBottom: scrolled ? "1px solid rgba(212,175,55,0.2)" : "none" }}
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      transition={{ duration: 0.6, ease: "easeOut" }}
    >
      <div className="flex items-center justify-between px-6 md:px-12 lg:px-24">
        <motion.a
          href="#top"
          className="flex items-center gap-3"
          whileHover={{ scale: 1.02 }}
        >
          <span className="serif tracking-[0.2em] uppercase" style={{ fontSize: 16, color: "#d4af37", fontWeight: 500 }}>D Sajawat</span>
          <motion.span
            className="hidden md:inline-block w-10 h-px"
            style={{ background: "rgba(212,175,55,0.5)" }}
            initial={{ width: 0 }}
            animate={{ width: 40 }}
            transition={{ delay: 0.5, duration: 0.5 }}
          />
          <span className="hidden md:inline serif italic" style={{ color: "rgba(26,8,10,0.6)", fontSize: 13 }}>Premium Fabrics</span>
          <motion.span
            className="hidden lg:inline-flex items-center gap-1 px-2 py-1 rounded-full text-[10px] font-semibold"
            style={{ background: "linear-gradient(135deg, #d4af37, #f4d77a)", color: "#1a080a" }}
            whileHover={{ scale: 1.1 }}
          >
            ⭐ Since 2012
          </motion.span>
        </motion.a>

        <nav className="hidden md:flex items-center gap-9">
          {links.map((l) => (
            <motion.a
              key={l.href}
              href={l.href}
              className="relative text-sm tracking-wider gold-accent-border pb-1"
              style={{ color: "rgba(26,8,10,0.7)" }}
              variants={linkVariants}
              initial="initial"
              whileHover="hover"
            >
              {l.label}
            </motion.a>
          ))}
          <motion.button
            onClick={onOpenQuote}
            className="btn-gold"
            style={{ padding: "10px 22px", fontSize: 13 }}
            variants={buttonVariants}
            initial="rest"
            whileHover="hover"
            whileTap="tap"
          >
            Request Quote
          </motion.button>
        </nav>

        {/* Mobile Menu Button */}
        <motion.button
          className="md:hidden text-[#1a080a]"
          onClick={() => setOpen((s) => !s)}
          whileTap={{ scale: 0.9 }}
        >
          <AnimatePresence mode="wait">
            {open ? (
              <motion.div
                key="close"
                initial={{ rotate: -90, opacity: 0 }}
                animate={{ rotate: 0, opacity: 1 }}
                exit={{ rotate: 90, opacity: 0 }}
                transition={{ duration: 0.2 }}
              >
                <X size={24} />
              </motion.div>
            ) : (
              <motion.div
                key="menu"
                initial={{ rotate: 90, opacity: 0 }}
                animate={{ rotate: 0, opacity: 1 }}
                exit={{ rotate: -90, opacity: 0 }}
                transition={{ duration: 0.2 }}
              >
                <Menu size={24} />
              </motion.div>
            )}
          </AnimatePresence>
        </motion.button>
      </div>

      {/* Mobile Menu */}
      <AnimatePresence>
        {open && (
          <motion.div
            className="md:hidden mx-6 mt-3 p-6 rounded-xl"
            style={{ background: "white", border: "1px solid rgba(212,175,55,0.3)", boxShadow: "0 8px 32px rgba(212,175,55,0.15)" }}
            variants={menuVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
          >
            <div className="flex flex-col gap-4">
              {links.map((l, i) => (
                <motion.a
                  key={l.href}
                  href={l.href}
                  onClick={() => setOpen(false)}
                  className="serif text-xl"
                  style={{ color: "#1a080a" }}
                  custom={i}
                  variants={menuLinkVariants}
                  initial="hidden"
                  animate="visible"
                  whileHover={{ x: 10, color: "#d4af37" }}
                >
                  {l.label}
                </motion.a>
              ))}
              <motion.button
                onClick={() => { setOpen(false); onOpenQuote(); }}
                className="btn-gold mt-2 self-start"
                variants={buttonVariants}
                initial="rest"
                whileHover="hover"
                whileTap="tap"
              >
                Request Quote
              </motion.button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.header>
  );
}
